// cache-aside read
User get(long id) {
  String k = "user:" + id;
  User u = redis.get(k);
  if (u != null) return u;
  u = db.findUser(id);
  redis.setex(k, 300 + rnd(30), u); // TTL with jitter
  return u;
}
// write: update DB, then DELETE the key (not update)
void update(User u) { db.save(u); redis.del("user:" + u.id); }

-- pessimistic
BEGIN;
SELECT * FROM seats WHERE id = 42 FOR UPDATE;
UPDATE seats SET status = 'HELD', user_id = 7 WHERE id = 42;
COMMIT;

-- optimistic
UPDATE docs SET body = ?, version = version + 1
WHERE id = ? AND version = ?;   -- 0 rows => conflict, retry

-- atomic, no read-modify-write race
UPDATE stock SET qty = qty - 1 WHERE sku = ? AND qty > 0;

